 1  // Pure validation helpers for the CardPlugin image upload route.
 2  
 3  const ALLOWED_MIME_TO_EXT = {
 4      'image/png': 'png',
 5      'image/jpeg': 'jpg',
 6      'image/webp': 'webp',
 7      'image/gif': 'gif',
 8  };
 9  
10  // Map an upload mimetype to a safe file extension, or null if not allowed.
11  // SVG is intentionally excluded (stored-XSS vector).
12  function extensionForMime(mimeType) {
13      if (typeof mimeType !== 'string') return null;
14      return ALLOWED_MIME_TO_EXT[mimeType.toLowerCase()] || null;
15  }
16  
17  // Reject anything that could escape the Missions/<mission> directory.
18  function isValidMission(mission) {
19      if (typeof mission !== 'string') return false;
20      if (mission.trim() === '') return false;
21      if (mission.includes('..')) return false;
22      if (mission.includes('/') || mission.includes('\\')) return false;
23      // A pure-dot name (e.g. ".") resolves to a directory segment, so the upload
24      // would land in the Missions root instead of a mission folder.
25      if (/^\.+$/.test(mission)) return false;
26      return true;
27  }
28  
29  module.exports = { ALLOWED_MIME_TO_EXT, extensionForMime, isValidMission };

